use vstd::prelude::*;

verus! {
    fn reverse(v: &mut Vec<u64>)
        requires
            v.len() <= u64::MAX as usize, // Ensure the length of the vector is within bounds
        ensures
            forall |i: nat| 0 <= i < v.len() as nat ==> v[i] == old(v)[(v.len() as nat - 1) - i],
    {
        let n = v.len() as nat; // Get the length of the vector
        let mut i: nat = 0; // Initialize the starting index
        let mut j: nat = n - 1; // Initialize the ending index

        while i < j
            invariant
                0 <= i <= j < n,
                forall |k: nat| 0 <= k < i ==> v[k] == old(v)[k], // Elements before i remain unchanged
                forall |k: nat| j < k < n ==> v[k] == old(v)[k], // Elements after j remain unchanged
                v[i] == old(v)[j], // The element at i is the original element at j
                v[j] == old(v)[i], // The element at j is the original element at i
            decreases j - i,
        {
            // Swap the elements at indices i and j
            let temp = v[i]; // Store the value at index i
            v[i] = v[j]; // Set index i to the value at index j
            v[j] = temp; // Set index j to the original value at index i

            // Move the indices towards the center
            i = i + 1;
            j = j - 1;
        }
    }
}

